  ('c56d443f-8eef-40f3-9461-31cf0e30663b', 'breastfeeding', 'avoid', 'Avoid in pregnancy/breastfeeding, existing liver disease, and Parkinson''s disease. | AVOID in: anyone with liver disease or abnormal LFTs, heavy alcohol users, pregnancy/breastfeeding, and children.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 9affddd3-2ee2-4014-bcac-8d2bf3345f1a, d875e192-9c79-42a9-af12-6a1b681892a1; signal "avoid", confidence high', 'draft'), -- kava
  ('c56d443f-8eef-40f3-9461-31cf0e30663b', 'children', 'avoid', 'AVOID in: anyone with liver disease or abnormal LFTs, heavy alcohol users, pregnancy/breastfeeding, and children.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links d875e192-9c79-42a9-af12-6a1b681892a1; signal "avoid", confidence medium', 'draft'), -- kava
  ('c56d443f-8eef-40f3-9461-31cf0e30663b', 'liver', 'avoid', 'avoid with other hepatotoxic drugs | The dominant safety concern is hepatotoxicity.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 9affddd3-2ee2-4014-bcac-8d2bf3345f1a, d875e192-9c79-42a9-af12-6a1b681892a1; signal "avoid", confidence high', 'draft'), -- kava
  ('c56d443f-8eef-40f3-9461-31cf0e30663b', 'pregnancy', 'avoid', 'Avoid in pregnancy/breastfeeding, existing liver disease, and Parkinson''s disease. | AVOID in: anyone with liver disease or abnormal LFTs, heavy alcohol users, pregnancy/breastfeeding, and children.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 9affddd3-2ee2-4014-bcac-8d2bf3345f1a, d875e192-9c79-42a9-af12-6a1b681892a1; signal "avoid", confidence high', 'draft'), -- kava
  ('c56d443f-8eef-40f3-9461-31cf0e30663b', 'surgery', 'caution', 'May potentiate anesthesia (stop before surgery).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links d875e192-9c79-42a9-af12-6a1b681892a1; signal "may potentiate", confidence high', 'draft'), -- kava
  ('69950e62-9bf5-467c-a50d-552b9ae573ad', 'kidney', 'caution', 'Consult a clinician if pregnant, on dialysis, on warfarin, or with cardiac or seizure history.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 55baefed-81ea-4574-8a18-379ec22c5c68; signal "consult", confidence high', 'draft'), -- l-carnitine
