  ('c958b4d2-dc00-48ea-b7ee-3b58f8178d86', 'breastfeeding', 'avoid', 'Not adequately studied in pregnancy/breastfeeding, in significant kidney or liver disease, or in children — avoid without a clinician.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links ae2c2be1-fb41-4fb6-8c5f-00059511976d; signal "avoid", confidence high', 'draft'), -- l-citrulline
