  ('99f922bb-5242-49d7-a33d-6bd71001638d', 'surgery', 'avoid', 'Because it may have mild antiplatelet/anti-inflammatory activity, use caution with anticoagulants/antiplatelet drugs (e.g., warfarin) and stop before surgery.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 501c264a-30a1-4bbe-9365-9389e5809e1c; signal "stop before", confidence high', 'draft'), -- msm
