  ('dd10e068-9e6e-4511-89ab-1e03659c9ec4', 'breastfeeding', 'avoid', 'Avoid in pregnancy and breastfeeding.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links e97d5183-1a18-4ebf-a641-6cf974d3775f; signal "avoid", confidence high', 'draft'), -- tongkat-ali
  ('dd10e068-9e6e-4511-89ab-1e03659c9ec4', 'kidney', 'avoid', 'Not recommended for individuals with heart, liver, or kidney disease without medical supervision.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links e97d5183-1a18-4ebf-a641-6cf974d3775f; signal "not recommended", confidence high', 'draft'), -- tongkat-ali
  ('dd10e068-9e6e-4511-89ab-1e03659c9ec4', 'pregnancy', 'avoid', 'Avoid in pregnancy and breastfeeding.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links e97d5183-1a18-4ebf-a641-6cf974d3775f; signal "avoid", confidence high', 'draft'), -- tongkat-ali
  ('76b9c61a-231a-4113-8334-9a93626529e0', 'kidney', 'avoid', 'Avoid in anyone with liver disease, kidney disease, or on other hepatotoxic drugs/supplements. | A 2024 case report (Mohy-Ud-Din) describes a 46-year-old man with 2 months of daily use who developed severe hepatotoxicity AND acute kidney injury (peak bilirubin 48 mg/dL, creatinine 7.1) requiring pla', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links c019baf8-3f13-460e-ad46-0a54baba4d65; signal "avoid", confidence high', 'draft'), -- tribulus
  ('76b9c61a-231a-4113-8334-9a93626529e0', 'liver', 'avoid', 'In livestock that graze on it, Tribulus causes fatal hepatogenous photosensitivity, so hepatotoxic potential is biologically real. | Most serious real risk: documented drug-induced liver injury (DILI).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links c019baf8-3f13-460e-ad46-0a54baba4d65; signal "fatal", confidence high', 'draft'), -- tribulus
  ('76b9c61a-231a-4113-8334-9a93626529e0', 'pregnancy', 'avoid', 'Not for use in pregnancy (traditional uterotonic/animal reproductive effects).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links c019baf8-3f13-460e-ad46-0a54baba4d65; signal "not for use", confidence low', 'draft'), -- tribulus
  ('2e9eda94-20ea-4003-a6b6-93ef8c82c946', 'breastfeeding', 'avoid', 'Avoid or use only with physician oversight if pregnant, breastfeeding, on multiple prescriptions, or on narrow-therapeutic-index drugs.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links da62699e-4c98-42c2-8ecb-362ea4484837; signal "avoid", confidence high', 'draft'), -- triphala
  ('2e9eda94-20ea-4003-a6b6-93ef8c82c946', 'pregnancy', 'avoid', 'Avoid or use only with physician oversight if pregnant, breastfeeding, on multiple prescriptions, or on narrow-therapeutic-index drugs.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links da62699e-4c98-42c2-8ecb-362ea4484837; signal "avoid", confidence high', 'draft'), -- triphala
  ('91d52399-861a-4536-9e8f-6656ad7e2419', 'bleeding_risk', 'avoid', 'Contraindications/avoid: gallstones or bile-duct obstruction (turmeric stimulates bile), active bleeding disorders, pregnancy at supplemental (non-food) doses, and iron-deficiency (curcumin can chelate iron).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 52d68ecf-974b-4e52-b26f-69081aadd250; signal "avoid", confidence high', 'draft'), -- turmeric
  ('91d52399-861a-4536-9e8f-6656ad7e2419', 'kidney', 'caution', 'High doses may cause GI upset, nausea, or diarrhea, and turmeric is high in oxalate (relevant for kidney-stone formers).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 85bbba37-02a3-474f-805e-e1f98d4f166b; signal "none", confidence low', 'draft'), -- turmeric
  ('91d52399-861a-4536-9e8f-6656ad7e2419', 'liver', 'avoid', 'avoid in active liver disease and if combined with hepatotoxic drugs. | LIVER-INJURY RISK (important given it is marketed FOR the liver): curcumin/turmeric is a documented cause of drug-induced liver injury (DILI), including cholestatic hepatitis and autoimmune-like hepatitis', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 8a79a553-6c44-4da3-aa7c-3d8cde9d06fd, b1352d2e-f708-478a-a432-d1fb4dc2e537, b3e1abbb-1c86-4140-95ba-15b8d0f4cbe3, 237ed832-c151-4120-99e5-155e0e69482e, 85bbba37-02a3-474f-805e-e1f98d4f166b, 8a3c3b38-fa7a-4520-8ce3-98cd8be6603b, 52d68ecf-974b-4e52-b26f-69081aadd250; signal "avoid", confidence high', 'draft'), -- turmeric
  ('91d52399-861a-4536-9e8f-6656ad7e2419', 'pregnancy', 'avoid', 'Avoid high-dose supplements in pregnancy. | Avoid high-dose supplements in pregnancy and with active gallstones/bile-duct obstruction.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 8a79a553-6c44-4da3-aa7c-3d8cde9d06fd, b1352d2e-f708-478a-a432-d1fb4dc2e537, b3e1abbb-1c86-4140-95ba-15b8d0f4cbe3, 237ed832-c151-4120-99e5-155e0e69482e, 85bbba37-02a3-474f-805e-e1f98d4f166b, 8a3c3b38-fa7a-4520-8ce3-98cd8be6603b, 52d68ecf-974b-4e52-b26f-69081aadd250; signal "avoid", confidence high', 'draft'), -- turmeric
  ('91d52399-861a-4536-9e8f-6656ad7e2419', 'surgery', 'avoid', 'Curcumin has antiplatelet/anticoagulant activity — caution or avoid with warfarin, DOACs, aspirin, or NSAIDs, and stop ~2 weeks before surgery due to bleeding risk. | stop before surgery.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links b1352d2e-f708-478a-a432-d1fb4dc2e537, b3e1abbb-1c86-4140-95ba-15b8d0f4cbe3, 237ed832-c151-4120-99e5-155e0e69482e, 85bbba37-02a3-474f-805e-e1f98d4f166b, 8a3c3b38-fa7a-4520-8ce3-98cd8be6603b, 52d68ecf-974b-4e52-b26f-69081aadd250; signal "stop 2 weeks before", confidence high', 'draft'), -- turmeric
  ('029ff5e0-b45d-4db5-bef9-dda78a3f8bde', 'breastfeeding', 'avoid', 'Who should avoid it: pregnant or breastfeeding women (insufficient safety data), children under ~3, and people with significant liver disease. | Pregnancy/breastfeeding — safety is not established', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 1d965707-5f92-4b9f-bdf9-9f334f51d446, 7ed46f99-1e34-4c79-8937-79ea411c3f67; signal "avoid", confidence high', 'draft'), -- valerian-root
  ('029ff5e0-b45d-4db5-bef9-dda78a3f8bde', 'children', 'avoid', 'Who should avoid it: pregnant or breastfeeding women (insufficient safety data), children under ~3, and people with significant liver disease.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 1d965707-5f92-4b9f-bdf9-9f334f51d446; signal "avoid", confidence high', 'draft'), -- valerian-root
  ('029ff5e0-b45d-4db5-bef9-dda78a3f8bde', 'liver', 'avoid', 'Who should avoid it: pregnant or breastfeeding women (insufficient safety data), children under ~3, and people with significant liver disease. | Hepatotoxicity — rare case reports of liver injury exist, usually with multi-herb products where causality is unclear (NIH LiverTox lists it), but caution ', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 1d965707-5f92-4b9f-bdf9-9f334f51d446, 7ed46f99-1e34-4c79-8937-79ea411c3f67; signal "avoid", confidence medium', 'draft'), -- valerian-root
  ('029ff5e0-b45d-4db5-bef9-dda78a3f8bde', 'pregnancy', 'avoid', 'Who should avoid it: pregnant or breastfeeding women (insufficient safety data), children under ~3, and people with significant liver disease. | Pregnancy/breastfeeding — safety is not established', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 1d965707-5f92-4b9f-bdf9-9f334f51d446, 7ed46f99-1e34-4c79-8937-79ea411c3f67; signal "avoid", confidence high', 'draft'), -- valerian-root
  ('029ff5e0-b45d-4db5-bef9-dda78a3f8bde', 'surgery', 'avoid', 'Stop 1-2 weeks before elective surgery because of additive effect with anesthesia. | Perioperative — discontinue before surgery due to interaction with anesthesia.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 1d965707-5f92-4b9f-bdf9-9f334f51d446, 7ed46f99-1e34-4c79-8937-79ea411c3f67; signal "stop 1 2 weeks before", confidence high', 'draft'), -- valerian-root
  ('2b5cabb9-941c-4b09-880f-9bac0744bd17', 'breastfeeding', 'avoid', 'Not for children or breastfeeding without clinician oversight.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 330f4001-f8a9-4f2a-ac53-fa7bcf2e73e6; signal "not for children", confidence high', 'draft'), -- vidanga
  ('2b5cabb9-941c-4b09-880f-9bac0744bd17', 'children', 'avoid', 'Not for children or breastfeeding without clinician oversight.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 330f4001-f8a9-4f2a-ac53-fa7bcf2e73e6; signal "not for children", confidence high', 'draft'), -- vidanga
  ('2b5cabb9-941c-4b09-880f-9bac0744bd17', 'liver', 'caution', 'theoretical additive risk with other antifertility or hepatotoxic agents.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 330f4001-f8a9-4f2a-ac53-fa7bcf2e73e6; signal "additive", confidence high', 'draft'), -- vidanga
  ('2b5cabb9-941c-4b09-880f-9bac0744bd17', 'pregnancy', 'avoid', 'REPRODUCTIVE: embelin is antispermatogenic/antifertility in males and anti-implantation/abortifacient — E. ribes is a component of investigational herbal contraceptives (PMID 11779954). | CONTRAINDICATED in pregnancy, in anyone who could become pregnant while untreated, and in men actively trying to', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 330f4001-f8a9-4f2a-ac53-fa7bcf2e73e6; signal "abortifacient", confidence high', 'draft'), -- vidanga
  ('168d2b5c-b5d9-4953-a971-7cca6f4b10f9', 'kidney', 'caution', 'high doses increase urinary oxalate and may raise kidney-stone risk in predisposed people | caution with a history of calcium-oxalate stones or renal impairment.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 98e46008-b6ef-4a97-bb29-798ea81866b1, 86997e61-851a-4cb4-bbfb-7e63c9d8c3e8; signal "may raise", confidence high', 'draft'), -- vitamin-c
  ('47552600-e2de-4704-8c76-861afaa4c309', 'elderly', 'caution', 'Large intermittent "bolus"/megadoses (e.g., single doses >100,000 IU or high monthly boluses) are not only less effective for infection prevention but have been linked to increased falls/fractures in older adults in some trials.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 16e2187e-2117-4be2-87b4-48cd0194e8e3; signal "none", confidence low', 'draft'), -- vitamin-d3
  ('47552600-e2de-4704-8c76-861afaa4c309', 'kidney', 'caution', 'Real risk is toxicity from chronic megadosing (typically >4000 IU/d long-term, or single very high boluses): hypercalcemia causing nausea, constipation, confusion, kidney stones, and kidney damage. | Real risks come from chronic high-dose overuse: hypercalcemia, hypercalciuria, kidney stones, and vi', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 16e2187e-2117-4be2-87b4-48cd0194e8e3, 10eb44b5-dd5c-4df5-af71-900f918bc394, 392d0520-2db4-4b77-91d2-3b25ed7d32e5, 811c70a3-4ab3-4b3e-863b-04647173690b; signal "risk", confidence medium', 'draft'), -- vitamin-d3
  ('89d32ff6-480a-48a3-8c69-4661de5bdc79', 'bleeding_risk', 'caution', 'active peptic ulcer or bleeding disorders', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 727ae5f4-f89d-4993-90d4-1c997509da41; signal "none", confidence low', 'draft'), -- willow-bark
  ('89d32ff6-480a-48a3-8c69-4661de5bdc79', 'breastfeeding', 'caution', 'Caution in pregnancy/breastfeeding (salicylate exposure) and in significant kidney or liver disease.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 727ae5f4-f89d-4993-90d4-1c997509da41; signal "caution", confidence high', 'draft'), -- willow-bark
  ('89d32ff6-480a-48a3-8c69-4661de5bdc79', 'children', 'avoid', 'Avoid in children/teenagers with fever or viral illness due to theoretical Reye''s syndrome risk shared with salicylates.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 727ae5f4-f89d-4993-90d4-1c997509da41; signal "avoid", confidence high', 'draft'), -- willow-bark
  ('89d32ff6-480a-48a3-8c69-4661de5bdc79', 'liver', 'caution', 'Caution in pregnancy/breastfeeding (salicylate exposure) and in significant kidney or liver disease.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 727ae5f4-f89d-4993-90d4-1c997509da41; signal "caution", confidence high', 'draft'), -- willow-bark
  ('89d32ff6-480a-48a3-8c69-4661de5bdc79', 'pregnancy', 'caution', 'Caution in pregnancy/breastfeeding (salicylate exposure) and in significant kidney or liver disease.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 727ae5f4-f89d-4993-90d4-1c997509da41; signal "caution", confidence high', 'draft'), -- willow-bark
  ('89d32ff6-480a-48a3-8c69-4661de5bdc79', 'surgery', 'caution', 'the week or two around surgery.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 727ae5f4-f89d-4993-90d4-1c997509da41; signal "none", confidence low', 'draft'), -- willow-bark
  ('6c1cf520-9526-4fa9-a9a2-e5b7e4d2b065', 'breastfeeding', 'avoid', 'CONTRAINDICATIONS: pregnancy and breastfeeding (traditional emmenagogue/abortifacient — avoid entirely)', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 310b3c0e-e679-472a-8015-7a85bf42ecb8; signal "contraindications", confidence high', 'draft'), -- wormwood
  ('6c1cf520-9526-4fa9-a9a2-e5b7e4d2b065', 'kidney', 'caution', 'Caution in kidney disease (renal irritation reported) and in anyone with prior alcohol-use issues if using tinctures.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 310b3c0e-e679-472a-8015-7a85bf42ecb8; signal "caution", confidence high', 'draft'), -- wormwood
  ('6c1cf520-9526-4fa9-a9a2-e5b7e4d2b065', 'pregnancy', 'avoid', 'CONTRAINDICATIONS: pregnancy and breastfeeding (traditional emmenagogue/abortifacient — avoid entirely)', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 310b3c0e-e679-472a-8015-7a85bf42ecb8; signal "contraindications", confidence high', 'draft'), -- wormwood
  ('8b8530b1-2ccc-44f2-916d-2eb2dca8b22d', 'breastfeeding', 'avoid', 'AVOID or use only under medical supervision if pregnant/breastfeeding, on multiple prescription medications, in kidney impairment, or on mineral-sensitive conditions (osteoporosis).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links e21b4ae1-ccfb-4c12-814a-4217fac888d8; signal "avoid", confidence high', 'draft'), -- zeolite
