insert into atlas_drug_interactions (ingredient_id, drug_class, severity, mechanism, note, source, status) values
  ('d9ca0504-2fe3-48fb-9c51-e2187296d9c3', 'antidepressants', 'avoid', 'serotonergic overlap (serotonin syndrome risk)', 'Serotonin syndrome: combining 5-HTP with SSRIs, SNRIs, MAOIs, tricyclics, triptans, tramadol, or other serotonergic agents can cause dangerous serotonin excess — do not combine without medical supervision | MAOIs are especially hazardous.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links d17c59dc-cbe9-4ac1-810c-846e48c05fa1; signal "dangerous", confidence medium', 'draft'), -- 5-htp
  ('d9ca0504-2fe3-48fb-9c51-e2187296d9c3', 'antipsychotics', 'caution', null, 'Common side effects are gastrointestinal (nausea, diarrhea, cramping), which peripheral decarboxylase inhibitors like carbidopa reduce in research settings but are not co-formulated in consumer products.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links d17c59dc-cbe9-4ac1-810c-846e48c05fa1; signal "none", confidence low', 'draft'), -- 5-htp
  ('47cffdce-5d63-4cc4-be9c-a61f28283b65', 'antidepressants', 'caution', 'electrolyte or mineral shift', 'KEY INTERACTION RISK: activated charcoal is an indiscriminate binder and will adsorb oral medications and nutrients, reducing their effectiveness — this includes prescription drugs (e.g., antidepressants, thyroid meds, seizure meds, oral contraceptives, blood-pressure and diabetes meds), vitamins, a', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 73f9fd10-9deb-4ddf-a1a5-addc73275088; signal "risk", confidence medium', 'draft'), -- activated-charcoal
  ('47cffdce-5d63-4cc4-be9c-a61f28283b65', 'antidiabetics', 'caution', 'electrolyte or mineral shift', 'KEY INTERACTION RISK: activated charcoal is an indiscriminate binder and will adsorb oral medications and nutrients, reducing their effectiveness — this includes prescription drugs (e.g., antidepressants, thyroid meds, seizure meds, oral contraceptives, blood-pressure and diabetes meds), vitamins, a', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 73f9fd10-9deb-4ddf-a1a5-addc73275088; signal "risk", confidence medium', 'draft'), -- activated-charcoal
  ('47cffdce-5d63-4cc4-be9c-a61f28283b65', 'antiepileptics', 'caution', 'electrolyte or mineral shift', 'KEY INTERACTION RISK: activated charcoal is an indiscriminate binder and will adsorb oral medications and nutrients, reducing their effectiveness — this includes prescription drugs (e.g., antidepressants, thyroid meds, seizure meds, oral contraceptives, blood-pressure and diabetes meds), vitamins, a', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 73f9fd10-9deb-4ddf-a1a5-addc73275088; signal "risk", confidence medium', 'draft'), -- activated-charcoal
  ('47cffdce-5d63-4cc4-be9c-a61f28283b65', 'hormonal', 'caution', 'hormonal activity', 'KEY INTERACTION RISK: activated charcoal is an indiscriminate binder and will adsorb oral medications and nutrients, reducing their effectiveness — this includes prescription drugs (e.g., antidepressants, thyroid meds, seizure meds, oral contraceptives, blood-pressure and diabetes meds), vitamins, a', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 73f9fd10-9deb-4ddf-a1a5-addc73275088; signal "risk", confidence medium', 'draft'), -- activated-charcoal
  ('47cffdce-5d63-4cc4-be9c-a61f28283b65', 'thyroid', 'caution', 'thyroid hormone effect', 'KEY INTERACTION RISK: activated charcoal is an indiscriminate binder and will adsorb oral medications and nutrients, reducing their effectiveness — this includes prescription drugs (e.g., antidepressants, thyroid meds, seizure meds, oral contraceptives, blood-pressure and diabetes meds), vitamins, a', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 73f9fd10-9deb-4ddf-a1a5-addc73275088; signal "risk", confidence medium', 'draft'), -- activated-charcoal
  ('77c6af02-c600-4bc9-b59a-ef91370c9bc3', 'antidiabetics', 'caution', 'additive blood-sugar lowering', 'Oral aloe may lower blood glucose (caution with diabetes meds/hypoglycemia) and rare hepatotoxicity has been reported with aloe supplements.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links ac48eb14-60bd-4604-9ba4-641d131fe227; signal "caution", confidence high', 'draft'), -- aloe-vera
  ('77c6af02-c600-4bc9-b59a-ef91370c9bc3', 'antihypertensives', 'caution', 'electrolyte or mineral shift', 'KEY RISK — product form matters: whole-leaf or non-decolorized aloe LATEX contains aloin/anthraquinones, a stimulant laxative that causes cramping, diarrhea, electrolyte loss (potassium depletion, which can potentiate digoxin and diuretics), and can worsen dehydration', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links ac48eb14-60bd-4604-9ba4-641d131fe227; signal "can potentiate", confidence high', 'draft'), -- aloe-vera
  ('e807f60e-ec3b-4e77-882a-e3abe61dae27', 'antidiabetics', 'caution', 'additive blood-sugar lowering', 'Main real-world side effect is hypoglycemia: ALA can lower blood glucose and may potentiate insulin/sulfonylureas - monitor closely in diabetics. | Rare insulin autoimmune syndrome (Hirata disease) with hypoglycemia has been reported, more in certain HLA genotypes.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 8c0fa763-826c-4d83-adaa-a0b1d65bc177; signal "may potentiate", confidence high', 'draft'), -- alpha-lipoic-acid
  ('e807f60e-ec3b-4e77-882a-e3abe61dae27', 'thyroid', 'caution', 'thyroid hormone effect', 'May reduce thyroid hormone levels/interfere with thyroid meds and can affect thiamine status in deficiency (e.g., heavy alcohol use).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 8c0fa763-826c-4d83-adaa-a0b1d65bc177; signal "can affect", confidence high', 'draft'), -- alpha-lipoic-acid
  ('2eaf28d1-8298-4712-9713-36442cf4de48', 'anticoagulants', 'caution', 'additive bleeding risk', 'It may have antiplatelet/anticoagulant activity — theoretical additive bleeding risk with warfarin, aspirin, or other blood thinners.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links b8789f0a-2818-495a-9699-50312df35433; signal "additive", confidence high', 'draft'), -- andrographis
  ('2eaf28d1-8298-4712-9713-36442cf4de48', 'antidiabetics', 'caution', 'additive blood-sugar lowering', 'It may lower blood pressure and blood glucose — possible additive effects with antihypertensives and antidiabetic drugs.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links b8789f0a-2818-495a-9699-50312df35433; signal "additive", confidence high', 'draft'), -- andrographis
  ('2eaf28d1-8298-4712-9713-36442cf4de48', 'antihypertensives', 'caution', 'additive blood-pressure or heart-rate lowering', 'It may lower blood pressure and blood glucose — possible additive effects with antihypertensives and antidiabetic drugs.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links b8789f0a-2818-495a-9699-50312df35433; signal "additive", confidence high', 'draft'), -- andrographis
  ('2eaf28d1-8298-4712-9713-36442cf4de48', 'immunosuppressants', 'caution', 'immune effects may add to or oppose the drug', 'Because it is immunomodulatory, caution is warranted in people with autoimmune disease or on immunosuppressants (theoretical, not well quantified).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links b8789f0a-2818-495a-9699-50312df35433; signal "caution", confidence high', 'draft'), -- andrographis
  ('83a7c53b-2b74-429b-85a7-b3b666b6e985', 'antidepressants', 'caution', null, 'Not a replacement for antidepressants', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 4f1bbe52-a46f-472d-96ca-f8cce754de10; signal "none", confidence low', 'draft'), -- ashwagandha
  ('83a7c53b-2b74-429b-85a7-b3b666b6e985', 'antidiabetics', 'caution', 'additive blood-sugar lowering', 'may enhance effects of thyroid, antidiabetic (hypoglycemia), and antihypertensive medications | May lower blood sugar and blood pressure (additive with antidiabetic/antihypertensive drugs).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 3d38cc44-a004-4414-9cc2-93ee6dcb633c, b0669d95-d3e5-4841-9c2f-892a7a82ed31, bb8a5d38-2eb5-4d5f-a7eb-1c8937374d40, 09be7cda-0a86-4c29-9818-df38d2a32c46; signal "may enhance", confidence high', 'draft'), -- ashwagandha
  ('83a7c53b-2b74-429b-85a7-b3b666b6e985', 'antiepileptics', 'caution', 'additive sedation', 'Sedative interaction - additive CNS depression with benzodiazepines, barbiturates, anticonvulsants, alcohol.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 79439568-0d31-42c1-b3ce-0b9c08b5eb50; signal "additive", confidence high', 'draft'), -- ashwagandha
  ('83a7c53b-2b74-429b-85a7-b3b666b6e985', 'antihypertensives', 'caution', 'additive blood-pressure or heart-rate lowering', 'may enhance effects of thyroid, antidiabetic (hypoglycemia), and antihypertensive medications | May lower blood sugar and blood pressure (additive with antidiabetic/antihypertensive drugs).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 3d38cc44-a004-4414-9cc2-93ee6dcb633c, b0669d95-d3e5-4841-9c2f-892a7a82ed31, bb8a5d38-2eb5-4d5f-a7eb-1c8937374d40, 09be7cda-0a86-4c29-9818-df38d2a32c46, 79439568-0d31-42c1-b3ce-0b9c08b5eb50; signal "may enhance", confidence high', 'draft'), -- ashwagandha
  ('83a7c53b-2b74-429b-85a7-b3b666b6e985', 'immunosuppressants', 'caution', 'immune effects may add to or oppose the drug', 'As a member of the nightshade family it can theoretically aggravate autoimmune conditions and may stimulate immune activity — caution with autoimmune disease (e.g., Hashimoto''s, lupus, RA) and with immunosuppressant drugs. | possible additive immunosuppressant interference.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 3d38cc44-a004-4414-9cc2-93ee6dcb633c, b0669d95-d3e5-4841-9c2f-892a7a82ed31, bb8a5d38-2eb5-4d5f-a7eb-1c8937374d40, 23b86ca9-8db2-49e0-8fa1-70468f394ea2, 09be7cda-0a86-4c29-9818-df38d2a32c46, 4f1bbe52-a46f-472d-96ca-f8cce754de10; signal "caution", confidence high', 'draft'), -- ashwagandha
  ('83a7c53b-2b74-429b-85a7-b3b666b6e985', 'sedatives', 'caution', 'additive sedation', 'INTERACTIONS: additive sedation with benzodiazepines, alcohol, other CNS depressants and anxiolytics | Sedative/CNS-depressant additive effects with benzodiazepines, alcohol, and other sedatives.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 3d38cc44-a004-4414-9cc2-93ee6dcb633c, b0669d95-d3e5-4841-9c2f-892a7a82ed31, bb8a5d38-2eb5-4d5f-a7eb-1c8937374d40, 23b86ca9-8db2-49e0-8fa1-70468f394ea2, 09be7cda-0a86-4c29-9818-df38d2a32c46, 79439568-0d31-42c1-b3ce-0b9c08b5eb50, 4f1bbe52-a46f-472d-96ca-f8cce754de10; signal "additive", confidence high', 'draft'), -- ashwagandha
  ('83a7c53b-2b74-429b-85a7-b3b666b6e985', 'thyroid', 'caution', 'thyroid hormone effect', 'It can lower or raise thyroid hormone activity (may increase T3/T4) — caution in hyperthyroidism and in anyone on levothyroxine (risk of pushing toward hyperthyroid). | It can raise thyroid hormone (T4) levels — caution or avoid in hyperthyroidism and monitor if on thyroid medication.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 3d38cc44-a004-4414-9cc2-93ee6dcb633c, b0669d95-d3e5-4841-9c2f-892a7a82ed31, bb8a5d38-2eb5-4d5f-a7eb-1c8937374d40, 23b86ca9-8db2-49e0-8fa1-70468f394ea2, 09be7cda-0a86-4c29-9818-df38d2a32c46, 79439568-0d31-42c1-b3ce-0b9c08b5eb50, 4f1bbe52-a46f-472d-96ca-f8cce754de10; signal "caution", confidence high', 'draft'), -- ashwagandha
  ('694c258a-ada1-4e40-90de-37e9fffb5afb', 'anticoagulants', 'caution', 'additive bleeding risk', 'Possible additive effects with anticoagulants and blood-pressure/diuretic medications', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 5b7af1ba-c595-46e5-be9b-0c49000a384a; signal "additive", confidence high', 'draft'), -- astragalus
  ('694c258a-ada1-4e40-90de-37e9fffb5afb', 'antidiabetics', 'caution', 'additive blood-sugar lowering', 'may lower blood sugar (watch with antidiabetic drugs).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 5b7af1ba-c595-46e5-be9b-0c49000a384a; signal "may lower", confidence high', 'draft'), -- astragalus
  ('694c258a-ada1-4e40-90de-37e9fffb5afb', 'antihypertensives', 'caution', 'additive bleeding risk', 'Possible additive effects with anticoagulants and blood-pressure/diuretic medications', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 5b7af1ba-c595-46e5-be9b-0c49000a384a; signal "additive", confidence high', 'draft'), -- astragalus
  ('694c258a-ada1-4e40-90de-37e9fffb5afb', 'immunosuppressants', 'avoid', 'immune effects may add to or oppose the drug', 'Immunostimulant activity means it may theoretically counteract immunosuppressant drugs — people on organ-transplant medication (e.g., cyclosporine, tacrolimus) or immune-suppressing therapy should avoid it or use only under medical supervision.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 5b7af1ba-c595-46e5-be9b-0c49000a384a; signal "avoid", confidence medium', 'draft'), -- astragalus
  ('fd51bcf8-6f47-4ca0-87a2-3cfd5e185bb5', 'antihypertensives', 'caution', 'changes the drug''s blood level (liver enzyme or transporter interaction)', 'It may add to sedation and could interact with drugs metabolized by the liver, calcium-channel blockers, and cholinergic/anticholinergic medications', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links a811c5bb-b81c-4335-8350-cbf4fd71a5d8; signal "may add", confidence high', 'draft'), -- bacopa-monnieri
  ('fd51bcf8-6f47-4ca0-87a2-3cfd5e185bb5', 'sedatives', 'caution', 'additive sedation', 'Potential additive sedation with CNS depressants, benzodiazepines, or alcohol.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links ec5425ec-d0d2-4e35-81d9-15a5581e10f9; signal "additive", confidence high', 'draft'), -- bacopa-monnieri
  ('fd51bcf8-6f47-4ca0-87a2-3cfd5e185bb5', 'thyroid', 'caution', 'thyroid hormone effect', 'It may increase thyroid hormone levels (animal data) — caution in hyperthyroidism or with thyroid medication. | It has cholinergic and thyroid-stimulating activity in animal models, so caution with thyroid disease or thyroid hormone (levothyroxine).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links ec5425ec-d0d2-4e35-81d9-15a5581e10f9, a811c5bb-b81c-4335-8350-cbf4fd71a5d8; signal "caution", confidence low', 'draft'), -- bacopa-monnieri
  ('9c76079c-ce3e-4667-a1b6-120de05c74ab', 'antihypertensives', 'caution', 'additive blood-pressure or heart-rate lowering', 'Blood pressure: nitrate lowers BP (a mechanism, not just a side effect), so it can compound the effect of antihypertensive drugs or cause lightheadedness in people who already run low | use caution if on BP medication or nitrates for heart disease.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 54a51570-df6b-47d1-91f1-d89fdd525dc2; signal "can compound", confidence high', 'draft'), -- beetroot
  ('8796577a-7d1e-4b24-845f-cae58049f104', 'anticoagulants', 'caution', 'additive bleeding risk', 'Also cautioned with other CYP3A4 substrates, statins, midazolam, and anticoagulants.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links e16639a0-014a-4e11-ba51-08d32f33d4ed; signal "cautioned", confidence high', 'draft'), -- berberine
  ('8796577a-7d1e-4b24-845f-cae58049f104', 'antihypertensives', 'avoid', 'changes the drug''s blood level (liver enzyme or transporter interaction)', 'Avoid in pregnant/nursing women, neonates, G6PD deficiency, and anyone on cyclosporine, digoxin, tacrolimus, or CYP3A4/P-gp-sensitive medications without physician oversight. | clinically relevant for transplant patients), digoxin (AUC up ~30-70%), and, per PBPK modeling, goldenseal/high-dose berber', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links e16639a0-014a-4e11-ba51-08d32f33d4ed; signal "avoid", confidence high', 'draft'), -- berberine
  ('8796577a-7d1e-4b24-845f-cae58049f104', 'immunosuppressants', 'avoid', 'changes the drug''s blood level (liver enzyme or transporter interaction)', 'Avoid in pregnant/nursing women, neonates, G6PD deficiency, and anyone on cyclosporine, digoxin, tacrolimus, or CYP3A4/P-gp-sensitive medications without physician oversight. | DRUG INTERACTIONS via P-glycoprotein and CYP3A — berberine inhibits intestinal P-gp and raises blood levels of narrow-thera', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links e16639a0-014a-4e11-ba51-08d32f33d4ed; signal "avoid", confidence high', 'draft'), -- berberine
  ('8796577a-7d1e-4b24-845f-cae58049f104', 'statins', 'caution', 'changes the drug''s blood level (liver enzyme or transporter interaction)', 'Also cautioned with other CYP3A4 substrates, statins, midazolam, and anticoagulants.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links e16639a0-014a-4e11-ba51-08d32f33d4ed; signal "cautioned", confidence high', 'draft'), -- berberine
  ('505ef9ea-c6f7-4755-883c-dcfad9a59aaf', 'immunosuppressants', 'caution', 'immune effects may add to or oppose the drug', 'Because beta-glucan activates innate immune cells ("trained immunity"), theoretical caution is warranted in autoimmune/autoinflammatory disease (e.g., lupus, RA, MS, IBD) and in people on immunosuppressants or biologics — discuss with a clinician.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 160a1c7d-0b78-4837-95f1-18a79af8d641; signal "caution", confidence high', 'draft'), -- beta-glucans
  ('46f2bb5c-00dd-45a0-83a5-e6d55195904c', 'antibiotics', 'caution', 'infection risk in vulnerable patients', 'as a pro-oxidant it is theoretically counterproductive with, and unstudied against, standard antifungals/antibiotics in vivo.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 6c9bba37-65a3-4960-8288-65b9deb999a7; signal "theoretically", confidence medium', 'draft'), -- black-walnut
  ('46f2bb5c-00dd-45a0-83a5-e6d55195904c', 'antifungals', 'caution', 'infection risk in vulnerable patients', 'as a pro-oxidant it is theoretically counterproductive with, and unstudied against, standard antifungals/antibiotics in vivo.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 6c9bba37-65a3-4960-8288-65b9deb999a7; signal "theoretically", confidence medium', 'draft'), -- black-walnut
  ('d28979e9-214a-4c9c-ac75-9c944e2ea88c', 'hormonal', 'caution', 'hormonal activity', 'Because boron can shift estrogen and testosterone-related markers, use caution with hormone-sensitive conditions and with hormone therapies. | No serious drug interactions are well documented, but data are limited — flag it to a prescriber if on hormone therapy or with renal impairment.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links c155070c-7ed2-48ac-93a0-b716973a0bd3; signal "caution", confidence high', 'draft'), -- boron
  ('f1f2418f-be01-4c8d-b662-0933d8ac8c8c', 'anticoagulants', 'caution', 'additive bleeding risk', 'Theoretical and mechanism-based cautions: boswellic acids may affect inflammatory and possibly platelet/leukotriene pathways, so use caution with anticoagulants/antiplatelets (warfarin, clopidogrel, aspirin) | Interactions: as a 5-LO/anti-inflammatory agent with CYP enzyme effects, it may interact w', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 8dc75b8d-cbdd-48b7-855c-d38c814e7423, be973666-9b29-43bd-a90c-bfdd474ad0c2; signal "caution", confidence high', 'draft'), -- boswellia
  ('f1f2418f-be01-4c8d-b662-0933d8ac8c8c', 'immunosuppressants', 'caution', 'immune effects may add to or oppose the drug', 'Interactions: as a 5-LO/anti-inflammatory agent with CYP enzyme effects, it may interact with anticoagulants/antiplatelets (bleeding risk), NSAIDs, immunosuppressants, and drugs metabolized by CYP3A4/CYP2C9/CYP2D6', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links be973666-9b29-43bd-a90c-bfdd474ad0c2; signal "may interact", confidence high', 'draft'), -- boswellia
  ('f1f2418f-be01-4c8d-b662-0933d8ac8c8c', 'nsaids', 'caution', 'additive bleeding risk', 'Interactions: as a 5-LO/anti-inflammatory agent with CYP enzyme effects, it may interact with anticoagulants/antiplatelets (bleeding risk), NSAIDs, immunosuppressants, and drugs metabolized by CYP3A4/CYP2C9/CYP2D6', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links be973666-9b29-43bd-a90c-bfdd474ad0c2; signal "may interact", confidence high', 'draft'), -- boswellia
  ('2078374b-9908-4930-af0c-213f9965708e', 'antibiotics', 'caution', 'reduced or delayed absorption; separate the doses', 'May enhance absorption/serum levels of some antibiotics (e.g., amoxicillin, tetracycline).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 09b3ea7b-cf6d-4661-97d8-c9856f41417c; signal "may enhance", confidence high', 'draft'), -- bromelain
  ('2078374b-9908-4930-af0c-213f9965708e', 'anticoagulants', 'caution', 'additive bleeding risk', 'Key risk is bleeding — bromelain has antiplatelet/fibrinolytic activity and may potentiate anticoagulants and antiplatelet drugs (warfarin, aspirin, clopidogrel, DOACs)', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 09b3ea7b-cf6d-4661-97d8-c9856f41417c; signal "may potentiate", confidence high', 'draft'), -- bromelain
  ('7c51e022-1e1b-493b-8f72-11c92d9181c6', 'anticoagulants', 'caution', 'additive bleeding risk', 'Bleeding/anticoagulation — theoretical additive effect with anticoagulant/antiplatelet drugs', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 21cafb1f-dfd1-4fb5-a269-40609e529723; signal "additive", confidence high', 'draft'), -- burdock
