  ('99f922bb-5242-49d7-a33d-6bd71001638d', 'anticoagulants', 'caution', 'additive bleeding risk', 'Because it may have mild antiplatelet/anti-inflammatory activity, use caution with anticoagulants/antiplatelet drugs (e.g., warfarin) and stop before surgery.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 501c264a-30a1-4bbe-9365-9389e5809e1c; signal "caution", confidence high', 'draft'), -- msm
  ('c0e806a6-4850-4393-ada7-f374f2a87510', 'antibiotics', 'caution', 'reduced or delayed absorption; separate the doses', 'It can reduce serum levels of some drugs (e.g., certain antibiotics if co-administered) — separate dosing.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 40befcd0-fc41-4e9c-a16f-0911c4d53592; signal "separate", confidence high', 'draft'), -- nac
  ('c0e806a6-4850-4393-ada7-f374f2a87510', 'anticoagulants', 'caution', 'additive bleeding risk', 'Theoretical interactions: NAC has mild antiplatelet/vasodilatory activity and may potentiate nitroglycerin (hypotension/headache) | use caution with anticoagulants/antiplatelets.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 40befcd0-fc41-4e9c-a16f-0911c4d53592, ee909004-aa78-43dd-bd22-4ccfa270209b; signal "may potentiate", confidence high', 'draft'), -- nac
  ('c0e806a6-4850-4393-ada7-f374f2a87510', 'antihypertensives', 'caution', 'additive blood-pressure or heart-rate lowering', 'Theoretical interactions: NAC has mild antiplatelet/vasodilatory activity and may potentiate nitroglycerin (hypotension/headache) | Interactions: NAC can potentiate nitroglycerin (hypotension/headache) and, because it is a reducing thiol, its antioxidant load may theoretically blunt some therapies.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 40befcd0-fc41-4e9c-a16f-0911c4d53592, ee909004-aa78-43dd-bd22-4ccfa270209b; signal "may potentiate", confidence high', 'draft'), -- nac
  ('c0e806a6-4850-4393-ada7-f374f2a87510', 'immunosuppressants', 'avoid', null, 'MAJOR contraindication/harm signal: in idiopathic pulmonary fibrosis, the combination of prednisone + azathioprine + NAC increased death and hospitalization (PANTHER-IPF, NEJM 2012) — that three-drug regimen must be avoided.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 40befcd0-fc41-4e9c-a16f-0911c4d53592; signal "death", confidence high', 'draft'), -- nac
  ('92327cd9-8d29-426e-81a1-a19bb66b9a55', 'antidiabetics', 'caution', 'additive blood-sugar lowering', 'INTERACTIONS: May potentiate blood-glucose lowering (additive with antidiabetic drugs → hypoglycemia risk) and may add to immunosuppressant/immunomodulatory effects | hypoglycemia risk (neem lowers blood glucose — additive with antidiabetic drugs/insulin)', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 61955a75-c2bc-4839-921b-4893556ba49e, 9dd21c55-ffd8-4b3b-90f2-417fb070579a; signal "additive", confidence high', 'draft'), -- neem
  ('92327cd9-8d29-426e-81a1-a19bb66b9a55', 'antihypertensives', 'caution', null, 'may potentiate anti-hypertensives.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 9dd21c55-ffd8-4b3b-90f2-417fb070579a; signal "may potentiate", confidence high', 'draft'), -- neem
  ('92327cd9-8d29-426e-81a1-a19bb66b9a55', 'immunosuppressants', 'caution', 'immune effects may add to or oppose the drug', 'INTERACTIONS: May potentiate blood-glucose lowering (additive with antidiabetic drugs → hypoglycemia risk) and may add to immunosuppressant/immunomodulatory effects | AVOID: infants/children (especially the oil), pregnant/breastfeeding women, people trying to conceive, those with liver disease, and ', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 61955a75-c2bc-4839-921b-4893556ba49e, 9dd21c55-ffd8-4b3b-90f2-417fb070579a; signal "may add", confidence high', 'draft'), -- neem
  ('637e3968-1484-4880-acab-d67f30417f5e', 'anticoagulants', 'caution', 'additive bleeding risk', 'Antiplatelet/anticoagulant effect — thymoquinone can inhibit platelet aggregation, so it may increase bleeding risk with warfarin, DOACs, aspirin/NSAIDs, or around surgery (stop ~2 weeks before surgery).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 7d7b0a46-5298-4160-a313-5a2c14228587; signal "may increase", confidence high', 'draft'), -- nigella-black-cumin
  ('637e3968-1484-4880-acab-d67f30417f5e', 'antidiabetics', 'caution', 'additive blood-sugar lowering', 'Hypoglycemia — it lowers blood glucose and can add to diabetes medications (metformin, sulfonylureas, insulin), risking low blood sugar.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 7d7b0a46-5298-4160-a313-5a2c14228587; signal "can add", confidence high', 'draft'), -- nigella-black-cumin
  ('637e3968-1484-4880-acab-d67f30417f5e', 'antihypertensives', 'caution', 'additive blood-pressure or heart-rate lowering', 'Hypotension — mild blood-pressure-lowering that can stack with antihypertensives.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 7d7b0a46-5298-4160-a313-5a2c14228587; signal "none", confidence low', 'draft'), -- nigella-black-cumin
  ('637e3968-1484-4880-acab-d67f30417f5e', 'nsaids', 'caution', 'additive bleeding risk', 'Antiplatelet/anticoagulant effect — thymoquinone can inhibit platelet aggregation, so it may increase bleeding risk with warfarin, DOACs, aspirin/NSAIDs, or around surgery (stop ~2 weeks before surgery).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 7d7b0a46-5298-4160-a313-5a2c14228587; signal "may increase", confidence high', 'draft'), -- nigella-black-cumin
  ('637e3968-1484-4880-acab-d67f30417f5e', 'sedatives', 'caution', 'additive sedation', 'Avoid or use only with clinician oversight in pregnancy (traditional emmenagogue/uterine-stimulant concern), and use caution when combining with sedatives.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 7d7b0a46-5298-4160-a313-5a2c14228587; signal "caution", confidence high', 'draft'), -- nigella-black-cumin
  ('4a2a320b-68d1-44d4-b3c0-c82b10a2263f', 'anticoagulants', 'caution', 'additive bleeding risk', 'use caution with warfarin, DOACs, aspirin/clopidogrel, and stop before elective surgery per your surgeon. | Antiplatelet/anticoagulant effect — high doses (roughly >3 g/d) modestly prolong bleeding time', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links e54a6332-5787-4c80-a89a-6c23024ea1ef, f5bd2530-8bbe-4470-a418-8163cef0d0a4, baaa87e5-e5e6-44d5-acef-2290cfb9d531; signal "caution", confidence high', 'draft'), -- omega-3-fish-oil
  ('4a2a320b-68d1-44d4-b3c0-c82b10a2263f', 'nsaids', 'caution', null, 'It does NOT rapidly relieve acute pain like an NSAID and is not a disease-modifying treatment for RA — it is an adjunct.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links f5bd2530-8bbe-4470-a418-8163cef0d0a4; signal "none", confidence low', 'draft'), -- omega-3-fish-oil
  ('c68efe6f-9bf2-4f3f-ac63-4f472897333f', 'anticoagulants', 'caution', 'additive bleeding risk', 'Carvacrol/thymol can inhibit platelet aggregation - use caution with anticoagulants/antiplatelets (warfarin, DOACs, clopidogrel, aspirin) and stop before surgery due to theoretical bleeding risk.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 3e1e198d-c5bc-47c4-9f69-931f65f5ce54; signal "caution", confidence high', 'draft'), -- oregano-oil
  ('c68efe6f-9bf2-4f3f-ac63-4f472897333f', 'antidiabetics', 'monitor', 'additive blood-sugar lowering', 'May have mild hypoglycemic effects - monitor if on diabetes medication (insulin, sulfonylureas).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 3e1e198d-c5bc-47c4-9f69-931f65f5ce54; signal "monitor", confidence high', 'draft'), -- oregano-oil
  ('e366f467-f748-44b0-9061-37146404e33a', 'anticoagulants', 'avoid', 'additive bleeding risk', 'WHO SHOULD AVOID: pregnant/breastfeeding women, people on blood thinners or diabetes medication, and anyone who cannot verify the plant''s identity/source. | INTERACTIONS (theoretical, not human-tested): contains coumarin-type constituents and phthalides — possible additive effect with anticoagulants', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 000e3c10-2e70-422b-9d1b-653013553dab; signal "avoid", confidence high', 'draft'), -- osha
  ('e366f467-f748-44b0-9061-37146404e33a', 'antidiabetics', 'avoid', 'additive blood-sugar lowering', 'WHO SHOULD AVOID: pregnant/breastfeeding women, people on blood thinners or diabetes medication, and anyone who cannot verify the plant''s identity/source. | possible additive blood-sugar lowering with antidiabetic drugs (osha constituents inhibit alpha-glucosidase and lowered glucose in diabetic mic', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 000e3c10-2e70-422b-9d1b-653013553dab; signal "avoid", confidence high', 'draft'), -- osha
  ('e366f467-f748-44b0-9061-37146404e33a', 'sedatives', 'caution', 'additive sedation', 'sedative/CNS-depressant and antispasmodic activity shown preclinically (PMID 21797735, https://doi.org/10.1080/14786419.2010.534735) — theoretical additive sedation.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 000e3c10-2e70-422b-9d1b-653013553dab; signal "additive", confidence medium', 'draft'), -- osha
  ('8c26bb3a-8ee1-4c17-840a-f4c04776e6d7', 'anticoagulants', 'caution', 'additive bleeding risk', 'Warfarin — ginseng can REDUCE warfarin''s anticoagulant effect (lower INR), a documented interaction | caution with all anticoagulants/antiplatelets.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 9e650cd7-b267-4f9b-9d35-209c87f82377, 15de03ff-0618-4b4e-a0a0-83a739872448, 828f553a-2c4b-4cd3-98d2-96dca0b927ef; signal "can reduce", confidence high', 'draft'), -- panax-ginseng
  ('8c26bb3a-8ee1-4c17-840a-f4c04776e6d7', 'antidepressants', 'caution', 'serotonergic overlap (serotonin syndrome risk)', 'MAO inhibitors (e.g., phenelzine) — case reports of mania/headache/tremor. | MAO inhibitors — case reports of interaction.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 9e650cd7-b267-4f9b-9d35-209c87f82377, 15de03ff-0618-4b4e-a0a0-83a739872448; signal "none", confidence low', 'draft'), -- panax-ginseng
  ('8c26bb3a-8ee1-4c17-840a-f4c04776e6d7', 'antidiabetics', 'caution', 'additive blood-sugar lowering', 'Diabetes drugs / insulin — ginseng can lower blood glucose and may cause additive hypoglycemia. | Diabetes/hypoglycemia — ginseng can lower blood glucose (a proposed mechanism for its acute cognitive effects), so it may add to the effect of insulin/oral hypoglycemics', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 9e650cd7-b267-4f9b-9d35-209c87f82377, 15de03ff-0618-4b4e-a0a0-83a739872448, 828f553a-2c4b-4cd3-98d2-96dca0b927ef; signal "can lower", confidence high', 'draft'), -- panax-ginseng
  ('8c26bb3a-8ee1-4c17-840a-f4c04776e6d7', 'immunosuppressants', 'caution', 'immune effects may add to or oppose the drug', 'Immunosuppressants — theoretical interference via immune stimulation.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 9e650cd7-b267-4f9b-9d35-209c87f82377; signal "theoretical", confidence medium', 'draft'), -- panax-ginseng
  ('8c26bb3a-8ee1-4c17-840a-f4c04776e6d7', 'stimulants', 'caution', 'additive stimulation', 'Stimulant-like effects mean caution with other stimulants, and it may worsen insomnia or anxiety.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 15de03ff-0618-4b4e-a0a0-83a739872448; signal "caution", confidence high', 'draft'), -- panax-ginseng
  ('0c3ed1a2-9d98-460e-b8a9-981c314ec670', 'anticoagulants', 'caution', 'additive bleeding risk', 'possible interaction with anticoagulants.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 4e7d9e8c-b06d-4284-a7d8-dc4127eee556; signal "possible", confidence medium', 'draft'), -- passionflower
  ('0c3ed1a2-9d98-460e-b8a9-981c314ec670', 'antidepressants', 'caution', 'serotonergic overlap (serotonin syndrome risk)', 'Theoretical additive effect with antihypertensives and with serotonergic/MAOI drugs', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 4e7d9e8c-b06d-4284-a7d8-dc4127eee556; signal "additive", confidence high', 'draft'), -- passionflower
  ('0c3ed1a2-9d98-460e-b8a9-981c314ec670', 'antihypertensives', 'caution', 'additive blood-pressure or heart-rate lowering', 'Theoretical additive effect with antihypertensives and with serotonergic/MAOI drugs', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 4e7d9e8c-b06d-4284-a7d8-dc4127eee556; signal "additive", confidence high', 'draft'), -- passionflower
  ('0c3ed1a2-9d98-460e-b8a9-981c314ec670', 'sedatives', 'caution', 'additive sedation', 'Because it is CNS-depressant/sedating, it can add to the effects of alcohol, benzodiazepines, barbiturates, opioids, sedating antihistamines, other sedative herbs (valerian, kava), and general anesthetics — use caution around driving/machinery and disclose before surgery/anesthesia. | trials reporte', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 4e7d9e8c-b06d-4284-a7d8-dc4127eee556, 8e2e0cbf-c90d-446d-be26-0312baeea485; signal "can add", confidence high', 'draft'), -- passionflower
  ('6145c3e3-d71d-4da0-b5dc-e4e8ddd91a1b', 'anticoagulants', 'avoid', 'additive bleeding risk', 'Do NOT combine with warfarin, DOACs (apixaban/rivaroxaban), heparin, antiplatelets (aspirin, clopidogrel), or other blood-thinning herbs | Lapachol is a vitamin-K-antagonist anticoagulant (inhibits vitamin-K epoxide and quinone reductase, mechanism similar to warfarin)', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links f50e9184-4507-4663-bfc7-31b971f777e3; signal "do not combine", confidence high', 'draft'), -- pau-darco
  ('6145c3e3-d71d-4da0-b5dc-e4e8ddd91a1b', 'chemotherapy', 'caution', null, 'Beta-lapachone is in oncology trials as an investigational drug (not an OTC dose reference).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links f50e9184-4507-4663-bfc7-31b971f777e3; signal "none", confidence low', 'draft'), -- pau-darco
  ('64dcc463-1ff5-43b6-ba2b-de31a2a233e4', 'sedatives', 'caution', 'additive sedation', 'it does not cause a "high," dependence, or the sedation/constipation of opioids.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 8747fdb2-e371-47f5-a072-1104465896c1; signal "none", confidence low', 'draft'), -- pea
  ('66260d61-03ac-4144-a81c-9009f4ae0c1b', 'acid_reducers', 'caution', 'reduced or delayed absorption; separate the doses', 'taking non-coated peppermint oil, chewing/crushing the capsules, or taking with antacids/PPIs (which can dissolve the coating early) increases reflux.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links b634af09-f9fa-497b-9689-2ba127d6a7d5; signal "none", confidence low', 'draft'), -- peppermint-oil
  ('66260d61-03ac-4144-a81c-9009f4ae0c1b', 'antihypertensives', 'caution', 'changes the drug''s blood level (liver enzyme or transporter interaction)', 'Drug interactions: menthol inhibits CYP3A4 and CYP1A2 in vitro, so theoretical potential to raise levels of some medications (e.g., certain statins, immunosuppressants, some calcium-channel blockers) — clinically modest but worth flagging for people on narrow-therapeutic-index drugs.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links b634af09-f9fa-497b-9689-2ba127d6a7d5; signal "potential", confidence low', 'draft'), -- peppermint-oil
  ('66260d61-03ac-4144-a81c-9009f4ae0c1b', 'immunosuppressants', 'caution', 'immune effects may add to or oppose the drug', 'Drug interactions: menthol inhibits CYP3A4 and CYP1A2 in vitro, so theoretical potential to raise levels of some medications (e.g., certain statins, immunosuppressants, some calcium-channel blockers) — clinically modest but worth flagging for people on narrow-therapeutic-index drugs.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links b634af09-f9fa-497b-9689-2ba127d6a7d5; signal "potential", confidence low', 'draft'), -- peppermint-oil
  ('66260d61-03ac-4144-a81c-9009f4ae0c1b', 'statins', 'caution', 'changes the drug''s blood level (liver enzyme or transporter interaction)', 'Drug interactions: menthol inhibits CYP3A4 and CYP1A2 in vitro, so theoretical potential to raise levels of some medications (e.g., certain statins, immunosuppressants, some calcium-channel blockers) — clinically modest but worth flagging for people on narrow-therapeutic-index drugs.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links b634af09-f9fa-497b-9689-2ba127d6a7d5; signal "potential", confidence low', 'draft'), -- peppermint-oil
  ('c81b9891-bc0c-4851-8a70-85c6f0d19851', 'anticoagulants', 'caution', 'additive bleeding risk', 'Theoretical, not well-documented, interaction: PS could add to the effects of blood-thinners (anticoagulant/antiplatelet drugs) and of cholinergic/anticholinergic medications—caution and physician review are reasonable if combining.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 232bb486-ff1a-4b37-a4cd-dff90e47da11; signal "caution", confidence medium', 'draft'), -- phosphatidylserine
  ('4b4502a6-108d-4bac-ba42-4a0e62e9c745', 'anticoagulants', 'caution', 'additive bleeding risk', 'It has vasodilatory/mild blood-pressure-lowering and antiplatelet effects - use caution with antihypertensives, anticoagulants/antiplatelets (warfarin, DOACs, aspirin, clopidogrel), and around surgery (theoretical bleeding risk', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links db8cc1d5-0537-4417-af87-befca2ab8d7d; signal "caution", confidence high', 'draft'), -- pine-bark
  ('4b4502a6-108d-4bac-ba42-4a0e62e9c745', 'antihypertensives', 'caution', 'additive blood-pressure or heart-rate lowering', 'It has vasodilatory/mild blood-pressure-lowering and antiplatelet effects - use caution with antihypertensives, anticoagulants/antiplatelets (warfarin, DOACs, aspirin, clopidogrel), and around surgery (theoretical bleeding risk', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links db8cc1d5-0537-4417-af87-befca2ab8d7d; signal "caution", confidence high', 'draft'), -- pine-bark
  ('4b4502a6-108d-4bac-ba42-4a0e62e9c745', 'hormonal', 'caution', null, 'do not position it as a testosterone or TRT substitute - the pooled meta-analysis found no testosterone effect.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links db8cc1d5-0537-4417-af87-befca2ab8d7d; signal "none", confidence low', 'draft'), -- pine-bark
  ('4b4502a6-108d-4bac-ba42-4a0e62e9c745', 'immunosuppressants', 'caution', 'immune effects may add to or oppose the drug', 'Because it may stimulate immune activity, caution is advised in autoimmune disease and with immunosuppressants.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links db8cc1d5-0537-4417-af87-befca2ab8d7d; signal "caution", confidence high', 'draft'), -- pine-bark
  ('4b4502a6-108d-4bac-ba42-4a0e62e9c745', 'pde5_inhibitors', 'caution', 'additive blood-pressure or heart-rate lowering', 'The efficacy formula (Prelox) contains L-arginine, which can additively lower blood pressure and may interact with PDE5 inhibitors (sildenafil/tadalafil) and nitrates - do not stack casually.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links db8cc1d5-0537-4417-af87-befca2ab8d7d; signal "may interact", confidence high', 'draft'), -- pine-bark
  ('adfdf7ec-6661-4baf-a59f-06b9e1992fb4', 'antibiotics', 'caution', 'reduced or delayed absorption; separate the doses', 'theoretically space dosing away from antibiotics, which kill the bacteria. | A 2018 Cell study (PMID 30193113) showed probiotics can delay recovery of the native gut microbiome after antibiotics, so "more is better" is not supported.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 04945d7c-172a-46d5-b9f9-690d72c2ce6c, e5743943-bed5-40e0-a3be-fa18e7dfef7b, 57c39e52-a281-4560-99a4-a55b2e3760bf; signal "space dosing", confidence high', 'draft'), -- probiotics
  ('adfdf7ec-6661-4baf-a59f-06b9e1992fb4', 'antidepressants', 'caution', null, 'Minimal known interactions with antidepressants', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 04945d7c-172a-46d5-b9f9-690d72c2ce6c; signal "none", confidence low', 'draft'), -- probiotics
  ('adfdf7ec-6661-4baf-a59f-06b9e1992fb4', 'chemotherapy', 'avoid', 'immune effects may add to or oppose the drug', 'SERIOUS RISKS in vulnerable groups: rare but documented bloodstream infections (bacteremia) and fungemia — Saccharomyces boulardii fungemia is specifically linked to patients with central venous catheters — reported in critically ill/ICU patients, the immunocompromised (chemotherapy, HIV, transplant', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links e5743943-bed5-40e0-a3be-fa18e7dfef7b, 3417cd19-5a8e-4dac-8e26-14fc374d6ed0; signal "serious risks", confidence medium', 'draft'), -- probiotics
  ('adfdf7ec-6661-4baf-a59f-06b9e1992fb4', 'immunosuppressants', 'avoid', 'immune effects may add to or oppose the drug', 'SERIOUS-RISK GROUPS: live bacteria can rarely cause bloodstream infection (bacteremia/fungemia, including with Saccharomyces boulardii) in people who are immunocompromised, critically ill, have a central venous catheter, short-gut/leaky-gut or recent major GI surgery, or are receiving intensive care', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 04945d7c-172a-46d5-b9f9-690d72c2ce6c, e5743943-bed5-40e0-a3be-fa18e7dfef7b, 3417cd19-5a8e-4dac-8e26-14fc374d6ed0, 57c39e52-a281-4560-99a4-a55b2e3760bf; signal "serious risk", confidence medium', 'draft'), -- probiotics
  ('388985fd-110e-425e-9c55-0aa70325f43d', 'antidepressants', 'monitor', 'changes the drug''s blood level (liver enzyme or transporter interaction)', 'relevant for drugs with narrow therapeutic index such as levothyroxine, lithium, carbamazepine, digoxin, and some diabetes meds — note psyllium can independently lower post-meal glucose, so watch for additive hypoglycemia in insulin/sulfonylurea users).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 79ccd860-66c7-45f8-8d26-eb330b582a6f; signal "watch for", confidence medium', 'draft'), -- psyllium
  ('388985fd-110e-425e-9c55-0aa70325f43d', 'antidiabetics', 'monitor', 'additive blood-sugar lowering', 'relevant for drugs with narrow therapeutic index such as levothyroxine, lithium, carbamazepine, digoxin, and some diabetes meds — note psyllium can independently lower post-meal glucose, so watch for additive hypoglycemia in insulin/sulfonylurea users).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 79ccd860-66c7-45f8-8d26-eb330b582a6f; signal "watch for", confidence high', 'draft'), -- psyllium
