  ('7a1518c3-0aa0-4ded-ac08-35b9456ec564', 'sedatives', 'caution', 'additive sedation', 'Plausible additive effect with other sedatives or supplemental melatonin, though not well characterized.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 4616f3c1-e32a-4d91-be37-f18001cf767b; signal "additive", confidence high', 'draft'), -- tart-cherry
  ('e3a4a927-27b4-48b1-9f45-78c7b0668f2d', 'anticoagulants', 'caution', 'additive bleeding risk', 'Theoretical estrogenic and antiplatelet activity: use caution with anticoagulant/antiplatelet drugs (bleeding risk) and hormone-sensitive conditions.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links b0c82861-6cdb-4477-9c20-ed55d68240ab; signal "caution", confidence high', 'draft'), -- thyme
  ('dd10e068-9e6e-4511-89ab-1e03659c9ec4', 'anticoagulants', 'caution', 'additive bleeding risk', 'Theoretical caution with drugs affected by androgen changes, anticoagulants/antiplatelets, antidiabetic agents (possible additive glucose-lowering), and propranolol (absorption interaction reported).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links e97d5183-1a18-4ebf-a641-6cf974d3775f; signal "caution", confidence high', 'draft'), -- tongkat-ali
  ('dd10e068-9e6e-4511-89ab-1e03659c9ec4', 'antidiabetics', 'caution', 'additive blood-sugar lowering', 'Theoretical caution with drugs affected by androgen changes, anticoagulants/antiplatelets, antidiabetic agents (possible additive glucose-lowering), and propranolol (absorption interaction reported).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links e97d5183-1a18-4ebf-a641-6cf974d3775f; signal "additive", confidence high', 'draft'), -- tongkat-ali
  ('dd10e068-9e6e-4511-89ab-1e03659c9ec4', 'antihypertensives', 'caution', 'additive bleeding risk', 'Theoretical caution with drugs affected by androgen changes, anticoagulants/antiplatelets, antidiabetic agents (possible additive glucose-lowering), and propranolol (absorption interaction reported).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links e97d5183-1a18-4ebf-a641-6cf974d3775f; signal "additive", confidence high', 'draft'), -- tongkat-ali
  ('76b9c61a-231a-4113-8334-9a93626529e0', 'hormonal', 'caution', null, 'Because it is a botanical "testosterone booster," it is frequently adulterated or combined with other actives (e.g., androstenedione/DHEA blends), which independently lower HDL and raise estradiol/DHT — read labels carefully.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links c019baf8-3f13-460e-ad46-0a54baba4d65; signal "carefully", confidence high', 'draft'), -- tribulus
  ('91d52399-861a-4536-9e8f-6656ad7e2419', 'anticoagulants', 'caution', 'additive bleeding risk', 'Other effects: GI upset/diarrhea, and because curcumin has some antiplatelet activity it may add to bleeding risk with anticoagulants/antiplatelets. | caution with warfarin, and it can lower plasma levels of some agents (e.g., reported tacrolimus/talinolol effects).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 8a79a553-6c44-4da3-aa7c-3d8cde9d06fd, b1352d2e-f708-478a-a432-d1fb4dc2e537, b3e1abbb-1c86-4140-95ba-15b8d0f4cbe3, 237ed832-c151-4120-99e5-155e0e69482e, 85bbba37-02a3-474f-805e-e1f98d4f166b, 8a3c3b38-fa7a-4520-8ce3-98cd8be6603b, 52d68ecf-974b-4e52-b26f-69081aadd250; signal "may add", confidence high', 'draft'), -- turmeric
  ('91d52399-861a-4536-9e8f-6656ad7e2419', 'antidiabetics', 'caution', 'additive blood-sugar lowering', 'May lower blood glucose (watch with diabetes meds) and iron absorption (can worsen iron-deficiency). | May lower blood glucose (watch with diabetes meds), can worsen reflux/gallbladder issues, and may reduce iron absorption.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 8a79a553-6c44-4da3-aa7c-3d8cde9d06fd, b1352d2e-f708-478a-a432-d1fb4dc2e537, b3e1abbb-1c86-4140-95ba-15b8d0f4cbe3, 237ed832-c151-4120-99e5-155e0e69482e, 8a3c3b38-fa7a-4520-8ce3-98cd8be6603b, 52d68ecf-974b-4e52-b26f-69081aadd250; signal "may lower", confidence high', 'draft'), -- turmeric
  ('91d52399-861a-4536-9e8f-6656ad7e2419', 'chemotherapy', 'caution', 'changes the drug''s blood level (liver enzyme or transporter interaction)', 'It inhibits CYP3A4, CYP2C9, P-glycoprotein and UGTs, so it can raise levels of many drugs (some statins, tacrolimus, some chemo agents, sulfasalazine).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 8a3c3b38-fa7a-4520-8ce3-98cd8be6603b; signal "can raise", confidence high', 'draft'), -- turmeric
  ('91d52399-861a-4536-9e8f-6656ad7e2419', 'immunosuppressants', 'caution', 'changes the drug''s blood level (liver enzyme or transporter interaction)', 'caution with warfarin, and it can lower plasma levels of some agents (e.g., reported tacrolimus/talinolol effects). | Immunosuppressed patients or those with autoimmune disease on immune-modulating therapy should consult a clinician given its immunomodulatory activity.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 8a79a553-6c44-4da3-aa7c-3d8cde9d06fd, 237ed832-c151-4120-99e5-155e0e69482e, 8a3c3b38-fa7a-4520-8ce3-98cd8be6603b; signal "can lower", confidence high', 'draft'), -- turmeric
  ('91d52399-861a-4536-9e8f-6656ad7e2419', 'nsaids', 'avoid', 'additive bleeding risk', 'Curcumin has antiplatelet/anticoagulant activity — caution or avoid with warfarin, DOACs, aspirin, or NSAIDs, and stop ~2 weeks before surgery due to bleeding risk.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links b1352d2e-f708-478a-a432-d1fb4dc2e537; signal "avoid", confidence high', 'draft'), -- turmeric
  ('91d52399-861a-4536-9e8f-6656ad7e2419', 'statins', 'caution', 'changes the drug''s blood level (liver enzyme or transporter interaction)', 'It inhibits CYP3A4, CYP2C9, P-glycoprotein and UGTs, so it can raise levels of many drugs (some statins, tacrolimus, some chemo agents, sulfasalazine).', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 8a3c3b38-fa7a-4520-8ce3-98cd8be6603b; signal "can raise", confidence high', 'draft'), -- turmeric
  ('029ff5e0-b45d-4db5-bef9-dda78a3f8bde', 'sedatives', 'caution', 'additive sedation', 'Sedation/CNS interactions: can add to the effect of alcohol, benzodiazepines, barbiturates, opioids, sedating antihistamines, and other CNS depressants — a real concern for the veteran population that is often already on sleep or pain medication. | It is not physically addictive, but abrupt disconti', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 1d965707-5f92-4b9f-bdf9-9f334f51d446, 7ed46f99-1e34-4c79-8937-79ea411c3f67; signal "can add", confidence high', 'draft'), -- valerian-root
  ('48a02c96-6fbf-4288-ac97-df4ea3eb10c4', 'acid_reducers', 'caution', 'reduced or delayed absorption; separate the doses', 'Metformin and long-term proton-pump inhibitors/H2 blockers lower B12 absorption, so users of these are a real at-risk group. | B12 absorption is reduced by long-term metformin and proton-pump inhibitors, and by pernicious anemia/atrophic gastritis (autoimmune loss of intrinsic factor) — these people', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 4b0cabb3-5111-4613-ac13-4d6273920f10, 7e460c22-ae99-45fb-ab36-c8e3fed6c27f; signal "risk", confidence medium', 'draft'), -- vitamin-b12
  ('48a02c96-6fbf-4288-ac97-df4ea3eb10c4', 'antidiabetics', 'caution', 'reduced or delayed absorption; separate the doses', 'Metformin and long-term proton-pump inhibitors/H2 blockers lower B12 absorption, so users of these are a real at-risk group. | B12 absorption is reduced by long-term metformin and proton-pump inhibitors, and by pernicious anemia/atrophic gastritis (autoimmune loss of intrinsic factor) — these people', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 4b0cabb3-5111-4613-ac13-4d6273920f10, 7e460c22-ae99-45fb-ab36-c8e3fed6c27f; signal "risk", confidence medium', 'draft'), -- vitamin-b12
  ('168d2b5c-b5d9-4953-a971-7cca6f4b10f9', 'chemotherapy', 'caution', null, 'high-dose supplementation may reduce efficacy of some chemotherapy agents (oncology coordination needed)', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 86997e61-851a-4cb4-bbfb-7e63c9d8c3e8; signal "may reduce", confidence high', 'draft'), -- vitamin-c
  ('47552600-e2de-4704-8c76-861afaa4c309', 'antibiotics', 'caution', null, 'some anticonvulsants, glucocorticoids, and rifampin lower vitamin D levels.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 16e2187e-2117-4be2-87b4-48cd0194e8e3; signal "none", confidence low', 'draft'), -- vitamin-d3
  ('47552600-e2de-4704-8c76-861afaa4c309', 'antiepileptics', 'caution', 'reduced or delayed absorption; separate the doses', 'some anticonvulsants, glucocorticoids, and rifampin lower vitamin D levels. | absorption is reduced by orlistat, cholestyramine, and some anticonvulsants/steroids.', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 16e2187e-2117-4be2-87b4-48cd0194e8e3, 392d0520-2db4-4b77-91d2-3b25ed7d32e5; signal "none", confidence low', 'draft'), -- vitamin-d3
  ('47552600-e2de-4704-8c76-861afaa4c309', 'antihypertensives', 'caution', 'electrolyte or mineral shift', 'Interactions: thiazide diuretics (additive hypercalcemia risk), digoxin (hypercalcemia potentiates toxicity) | Can interact with thiazide diuretics (additive hypercalcemia) and digoxin', 'rule-based extraction from atlas_links.safety_note by scripts/draft-safety-rows.mjs (no model); links 16e2187e-2117-4be2-87b4-48cd0194e8e3, 10eb44b5-dd5c-4df5-af71-900f918bc394, 392d0520-2db4-4b77-91d2-3b25ed7d32e5, 811c70a3-4ab3-4b3e-863b-04647173690b; signal "additive", confidence high', 'draft'), -- vitamin-d3
